import { cursor } from './cursor';
import { gamePaused } from './game';
import { gameStore } from './gameStore';
import { derived } from 'svelte/store';

export const keyboardDisabled = derived(
	[cursor, gameStore.initialGrid, gamePaused],
	([$cursor, $initialGrid, $gamePaused]) => {
		return ($cursor.x === null && $cursor.y === null) || $initialGrid[$cursor.y][$cursor.x] !== 0 || $gamePaused;
	},
	false,
);